<?php
 namespace App\Http\Controllers; use App\Libraries\Template; use App\Services\Dapcode\LicenseGuard; use App\Services\HMVC\HMVC; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Illuminate\Foundation\Bus\DispatchesJobs; use Illuminate\Foundation\Validation\ValidatesRequests; use Illuminate\Http\JsonResponse; use Illuminate\Routing\Controller as BaseLaravelController; class Controller extends BaseLaravelController { use AuthorizesRequests, DispatchesJobs, ValidatesRequests; protected $template; public function __construct() { $this->template = app(Template::class); if (property_exists($this, 'moduleName') && !empty($this->moduleName)) { $canonicalModule = HMVC::resolveCanonicalModuleName($this->moduleName); if ($canonicalModule) { HMVC::enforceNoCrossModule($this->moduleName); LicenseGuard::assertModuleAllowed($canonicalModule); } } } protected function render(string $view, array $data = [], bool $return = false) { if (strpos($view, '::') !== false) { [$viewNs, $viewFile] = explode('::', $view, 2); $canonicalModule = HMVC::resolveCanonicalModuleName($viewNs); $availableModules = LicenseGuard::getAllAvailableModules(); if ($canonicalModule && in_array($canonicalModule, $availableModules, true)) { LicenseGuard::assertModuleAllowed($canonicalModule); } } if (!$this->template) { $this->template = app(Template::class); } return $this->template->render($view, $data, $return); } protected function moduleRender(string $view, array $data = [], bool $return = false) { $moduleKey = property_exists($this, 'moduleName') && !empty($this->moduleName) ? strtolower($this->moduleName) : 'app'; $canonicalModule = HMVC::resolveCanonicalModuleName($moduleKey); if ($canonicalModule && $canonicalModule !== 'app') { LicenseGuard::assertModuleAllowed($canonicalModule); } $viewPath = strpos($view, '::') === false ? "{$moduleKey}::{$view}" : $view; $payload = array_merge(['moduleName' => $this->moduleName ?? ucfirst($moduleKey)], $data); return $this->render($viewPath, $payload, $return); } protected function jsonResponse($data = null, string $message = 'Success', int $code = 200): JsonResponse { return response()->json([ 'status' => 'success', 'code' => $code, 'message' => $message, 'data' => $data, ], $code); } protected function jsonError(string $message = 'Error', int $code = 400, array $errors = []): JsonResponse { return response()->json([ 'status' => 'error', 'code' => $code, 'message' => $message, 'errors' => $errors, ], $code); } protected function hmvc(string $target, array $parameters = []) { return HMVC::run($target, $parameters); } } 